create table if not exists platform_config_version(id uuid primary key,version_number integer not null unique,status varchar(24) not null check(status in('DRAFT','PUBLISHED','ARCHIVED')),environment varchar(64) not null,reason text,created_by varchar(200) not null,created_at timestamptz not null default now(),published_by varchar(200),published_at timestamptz,based_on_version uuid references platform_config_version(id));
create table if not exists platform_config_value(id bigserial primary key,version_id uuid not null references platform_config_version(id) on delete cascade,config_key varchar(240) not null,value_text text,is_secret boolean not null default false,secret_fingerprint varchar(128),scope_type varchar(40) not null default 'GLOBAL',scope_key varchar(200) not null default '',updated_by varchar(200) not null,updated_at timestamptz not null default now(),unique(version_id,config_key,scope_type,scope_key));
create table if not exists platform_config_activation(id bigserial primary key,version_id uuid not null references platform_config_version(id),environment varchar(64) not null,activated_by varchar(200) not null,activated_at timestamptz not null default now(),deactivated_at timestamptz);
create unique index if not exists ux_platform_config_active_environment on platform_config_activation(environment) where deactivated_at is null;
create table if not exists platform_config_audit(id bigserial primary key,version_id uuid references platform_config_version(id),actor varchar(200) not null,action varchar(80) not null,target_key varchar(240),result varchar(40) not null,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists ix_platform_config_audit_created on platform_config_audit(created_at desc);